SELECT COUNT(1)
FROM procurement_operation_log l
LEFT JOIN contract c ON l.business_type = 1 AND l.data_id = c.id
WHERE 1 = 1


    AND () LIKE
        (CONVERT(CONCAT('%', #{dataName}, '%') USING utf8mb4) COLLATE utf8mb4_unicode_ci)


    AND l.business_type = #{businessType}


    AND () = #{operationType}


    AND (l.operator_name LIKE CONCAT('%', #{operator}, '%')
         OR CAST(l.operator_id AS CHAR) LIKE CONCAT('%', #{operator}, '%'))


    AND l.create_time >= #{startTime}


    AND l.create_time < #{endTime}

SELECT

FROM procurement_operation_log l
LEFT JOIN contract c ON l.business_type = 1 AND l.data_id = c.id
WHERE 1 = 1

    AND () LIKE
        (CONVERT(CONCAT('%', #{dataName}, '%') USING utf8mb4) COLLATE utf8mb4_unicode_ci)


    AND l.business_type = #{businessType}


    AND () = #{operationType}


    AND (l.operator_name LIKE CONCAT('%', #{operator}, '%')
         OR CAST(l.operator_id AS CHAR) LIKE CONCAT('%', #{operator}, '%'))


    AND l.create_time >= #{startTime}


    AND l.create_time < #{endTime}

ORDER BY l.create_time DESC, l.id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT data_id, MAX(create_time) AS create_time FROM procurement_operation_log WHERE business_type = 1 AND operation_type = 'URGE_SIGN' AND data_id IN
#{contractId}
GROUP BY data_id
